241	    if (typeof value === 'object') {
242	        const legacyMap = value as Record<string, unknown>;
243	        const entries = Object.entries(legacyMap);
244	
245	        // Empty legacy object → return undefined (no credentials configured).
246	        if (entries.length === 0) {
247	            return undefined;
248	        }
249	
250	        const result: GitCredentialEntry[] = [];
251	        const usedIds = new Set<string>();
252	
253	        for (const [index, [host, token]] of entries.entries()) {
254	            if (typeof token !== 'string') {
255	                throw new Error(
256	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must have a string value, got ${typeof token}.`
257	                );
258	            }
259	            if (token === '') {
260	                throw new Error(
261	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must not have an empty string value.`
262	                );
263	            }
264	
265	            // Derive a kebab-case ID from the hostname.
266	            const baseId = toKebabCase(host);
267	            let candidateId = baseId;
268	            let suffix = 2;
269	            while (usedIds.has(candidateId)) {
270	                candidateId = `${baseId}-${suffix}`;
271	                suffix++;
272	            }
273	            usedIds.add(candidateId);
274	
275	            result.push({
276	                id: candidateId,
277	                label: host,
278	                host,
279	                token,
280	            });
281	        }
282	
283	        return result;
284	    }
285	
286	    throw new Error(
287	        'Configuration error: "gitCredentials" must be an array of credential entries or omitted.'
288	    );
